INSERT INTO nation SELECT seed.* REPLACE (((SELECT max(n_nationkey) FROM nation)+1) AS n_nationkey, 'Q5 TERRITORY' AS n_name, (SELECT r_regionkey FROM region WHERE r_name='ASIA') AS n_regionkey, 'q5 new territory' AS n_comment) FROM nation seed ORDER BY n_nationkey LIMIT 1;
UPDATE customer SET c_nationkey=(SELECT n_nationkey FROM nation WHERE n_comment='q5 new territory'), c_comment='q5 territory customer' WHERE c_custkey=(SELECT min(c_custkey) FROM customer WHERE c_comment='q5 fixture customer');
UPDATE supplier SET s_nationkey=(SELECT n_nationkey FROM nation WHERE n_comment='q5 new territory'), s_comment='q5 territory supplier' WHERE s_comment='q5 fixture supplier' AND s_name='Q5 supplier:' || (SELECT split_part(c_name, ':', 2) FROM customer WHERE c_comment='q5 territory customer');
